/* Sourcewell RFP #110426 digital procurement demonstration.
   Visual interaction patterns adapted from the supplied UI replica.
   All people, sellers, transactions, stock, prices, login and connections are simulated. */
'use strict';
const STORE='pcl_sourcewell_110426_demo_v3',LOGIN='pcl_sourcewell_login_v3';
const PEOPLE={
 requester:{name:'Amelia Brooks',title:'Department Requester',org:'Sample Public Agency',icon:'🛍️',home:'My Purchasing Workspace',desc:'Find approved supplies, request purchases and track delivery.'},
 approver:{name:'Jordan Ellis',title:'Department Approver',org:'Sample Public Agency',icon:'✅',home:'Approvals & Team Spend',desc:'Authorize purchases against policy, budget and department need.'},
 procurement:{name:'Taylor Morgan',title:'Procurement Officer',org:'Sample Public Agency',icon:'📦',home:'Procurement Command Center',desc:'Manage requisitions, supplier awards, purchase orders and receipts.'},
 supplier:{name:'Casey Reed',title:'Supplier Partner',org:'Sample Office Supply Co.',icon:'🚚',home:'Supplier Collaboration',desc:'Confirm purchase orders, update shipments and submit invoices.'},
 finance:{name:'Morgan Lee',title:'Finance & Accounts Payable',org:'Sample Public Agency',icon:'💳',home:'Financial Operations',desc:'Reconcile purchase commitments, 3-way matches and payment postings.'},
 admin:{name:'Alex Grant',title:'Platform Administrator',org:'Sample Public Agency',icon:'⚙️',home:'Security & Platform Control',desc:'Manage roles, purchasing policies, integration jobs and exports.'}
};
const NAV={
 requester:[['home','Home','⌂'],['catalog','Shopping catalog','▦'],['cart','My basket','▤'],['requisitions','My requisitions','≡'],['orders','My orders','▧'],['profile','My profile','◉']],
 approver:[['home','My dashboard','⌂'],['approvals','Approval inbox','✓'],['requisitions','Team requisitions','≡'],['budgets','Team budgets','▥'],['reports','Team insights','◫'],['profile','My profile','◉']],
 procurement:[['home','Operations overview','⌂'],['requisitions','Requisitions','≡'],['orders','Purchase orders','▧'],['receiving','Goods receiving','⬓'],['catalog','Product catalogs','▦'],['contracts','Enterprise contracts','▣'],['suppliers','Supplier directory','♧'],['reports','Spend analytics','◫'],['audit','Audit trail','⛨'],['profile','My profile','◉']],
 supplier:[['home','Supplier overview','⌂'],['supplierorders','Incoming orders','▧'],['catalog','My catalog','▦'],['invoices','My invoices','▥'],['profile','Company profile','◉']],
 finance:[['home','Finance overview','⌂'],['invoices','AP invoices','▥'],['orders','Purchase commitments','▧'],['budgets','Budgets & cost centers','▤'],['reports','Finance analytics','◫'],['audit','Financial audit log','⛨'],['profile','My profile','◉']],
 admin:[['home','System overview','⌂'],['users','Identity & access','♙'],['policies','Approval policies','⚑'],['integrations','ERP & punchout','↔'],['suppliers','Seller governance','♧'],['contracts','Contract registry','▣'],['catalog','Catalog moderation','▦'],['tax','Tax exemptions','◇'],['reports','Analytics','◫'],['audit','Audit & exports','⛨'],['profile','My profile','◉']]
};
const CATS=['Office supplies','Janitorial & facilities','Safety & PPE','Technology accessories'];
const CATICON={'Office supplies':'📄','Janitorial & facilities':'🧹','Safety & PPE':'🦺','Technology accessories':'🖥️'};
function seed(){return {
 version:3,sequence:1106,policies:{approvalLimit:5000,variance:0,taxRate:5,retention:'Illustrative only — no production policy'},
 users:Object.entries(PEOPLE).map(([id,p])=>({id,name:p.name,title:p.title,email:`${p.name.toLowerCase().replace(/ /g,'.')}@demo.invalid`,enabled:true})),
 suppliers:[{id:'S1',name:'Sample Office Supply Co.',category:'Office supplies',region:'North America (illustrative)',diversity:'Unverified',status:'Approved',contact:'orders@example.invalid'},
 {id:'S2',name:'Sample Facility Essentials',category:'Janitorial & facilities',region:'Canada / US sample',diversity:'Unverified',status:'Approved',contact:'facility@example.invalid'},
 {id:'S3',name:'Sample Safety Distribution',category:'Safety & PPE',region:'North America (illustrative)',diversity:'Unverified',status:'Approved',contact:'safety@example.invalid'},
 {id:'S4',name:'Sample Technology Store',category:'Technology accessories',region:'Canada / US sample',diversity:'Unverified',status:'Approved',contact:'tech@example.invalid'}],
 products:[
 ['P1','Letter copy paper · 10 reams','Office supplies',42,'S1','OFF-PPR-001','case'],['P2','Ballpoint pens · 50 pack','Office supplies',21,'S1','OFF-PEN-002','pack'],['P3','Printer ink · black cartridge','Office supplies',64,'S1','OFF-INK-003','each'],
 ['P4','Surface cleaner · 4 L','Janitorial & facilities',29,'S2','FAC-CLE-004','bottle'],['P5','Paper towel rolls · case','Janitorial & facilities',48,'S2','FAC-TWL-005','case'],['P6','Waste liners · 100 pack','Janitorial & facilities',37,'S2','FAC-LNR-006','pack'],
 ['P7','Safety gloves · box of 100','Safety & PPE',32,'S3','PPE-GLV-007','box'],['P8','Protective eyewear','Safety & PPE',16,'S3','PPE-EYE-008','pair'],['P9','Hi-vis vest','Safety & PPE',23,'S3','PPE-VST-009','each'],
 ['P10','Ergonomic keyboard','Technology accessories',79,'S4','TEC-KBD-010','each'],['P11','USB-C docking hub','Technology accessories',135,'S4','TEC-HUB-011','each'],['P12','Wireless headset','Technology accessories',89,'S4','TEC-HST-012','each']
 ].map(([id,name,category,price,supplier,sku,unit])=>({id,name,category,price,supplier,sku,unit,status:'Active',stock:80})),
 contracts:[{id:'CON-1001',name:'Sample Operational Supply Framework',supplier:'S1',ceiling:40000,spent:3000,status:'Active',expires:'2027-12-31',terms:'Illustrative procurement terms; not a Sourcewell awarded contract.'}],
 budgets:[{id:'DEP-100',name:'Facilities & Administration',limit:40000,spent:1450},{id:'DEP-200',name:'Technology Services',limit:60000,spent:4200},{id:'DEP-300',name:'Public Works',limit:35000,spent:650}],
 tax:[{id:'TAX-1001',entity:'Sample Public Agency',certificate:'DEMO-EXEMPT-2026',status:'Needs validation',expiry:'2027-06-30'}],
 requisitions:[
 {id:'REQ-1001',owner:'requester',department:'DEP-100',purpose:'Quarterly office restocking',items:[{product:'P1',qty:3}],total:126,status:'Pending approval',created:'2026-11-02',notes:'Demo request awaiting departmental approval'},
 {id:'REQ-1002',owner:'requester',department:'DEP-300',purpose:'Worksite protective supplies',items:[{product:'P7',qty:10}],total:320,status:'Approved',created:'2026-10-30',notes:'Ready for purchasing'}],
 orders:[{id:'PO-1000',request:'REQ-0999',owner:'requester',supplier:'S1',department:'DEP-100',items:[{product:'P2',qty:4,price:21}],total:84,shipCost:0,taxAmount:0,status:'Received',tracking:'DEMO-TRACK-001',carrier:'Sample Delivery',created:'2026-10-25',received:4,contract:'CON-1001',paid:true}],
 receipts:[{id:'GR-1000',po:'PO-1000',qty:4,created:'2026-10-27',by:'procurement',note:'All units accepted'}],
 invoices:[{id:'INV-1000',po:'PO-1000',supplier:'S1',amount:84,number:'SAMPLE-INV-001',status:'Paid',created:'2026-10-28'}],
 cart:[],integrations:[{id:'ERP',name:'Finance ERP purchase-order export',status:'Ready (simulation)',last:'Not run'},{id:'PUNCHOUT',name:'Punchout supplier catalog exchange',status:'Ready (simulation)',last:'Not run'},{id:'SSO',name:'Corporate SSO / OIDC handshake',status:'Demonstration mode',last:'Not run'}],
 audit:[{id:'LOG-1000',by:'system',action:'DEMO INITIALIZED',subject:'Synthetic sample tenant',time:'2026-11-02 09:00',detail:'No live customer transactions or supplier links'}]
};}
let db;try{let raw=JSON.parse(localStorage.getItem(STORE)||'null');db=raw&&raw.version===3?raw:seed()}catch(e){db=seed()}
let role=sessionStorage.getItem(LOGIN)||'',page='home',ui={search:'',category:'All',filter:'All',selected:'',notifications:false};
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'CAD '+Number(v||0).toLocaleString('en-CA',{style:'decimal',minimumFractionDigits:2,maximumFractionDigits:2});
const int=v=>Number(v||0).toLocaleString('en-CA');
const date=()=>new Date().toISOString().slice(0,10);const timestamp=()=>new Date().toLocaleString('en-CA',{hour12:false});
const byid=(key,id)=>db[key].find(x=>x.id===id);
const prod=id=>byid('products',id)||{name:'Unknown item',price:0,supplier:'',category:'Unknown',sku:id,unit:'each'};
const sup=id=>(byid('suppliers',id)||{}).name||'Unassigned sample seller';
const dept=id=>(byid('budgets',id)||{}).name||id;
const next=prefix=>`${prefix}-${++db.sequence}`;
function save(){localStorage.setItem(STORE,JSON.stringify(db))}
function audit(action,subject,detail=''){db.audit.unshift({id:next('LOG'),by:role||'system',action,subject,time:timestamp(),detail});save()}
function toast(msg){let x=$('#toast');x.textContent=msg;x.classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>x.classList.remove('visible'),3500)}
function status(v){let k=/^(Paid|Active|Approved|Matched|Received|Shipped|Completed|Delivered)$/i.test(v)?'green':/Rejected|Suspended|Mismatch|Failed|Cancelled/i.test(v)?'red':/Pending|Review|Escalated|Draft|Issued|Ready|Needs|Awaiting|Submitted/i.test(v)?'orange':'gray';return `<span class="badge ${k}">${esc(v)}</span>`}
function button(action,label,cls='',id='',extra=''){return `<button class="btn ${cls}" data-action="${esc(action)}" ${id?`data-id="${esc(id)}"`:''} ${extra}>${label}</button>`}
function pgbutton(pg,label,cls=''){return `<button class="btn ${cls}" data-page="${pg}">${label}</button>`}
function head(title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${esc(PEOPLE[role]?.title||'Workplace')}</div><h1>${esc(title)}</h1><p class="sub">${esc(description)}</p></div><div class="actions">${actions}</div></div>`}
function box(title,content,link=''){return `<section class="card"><div class="section-top"><h3>${title}</h3>${link}</div>${content}</section>`}
function table(headers,rows){return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">No records in this view. Try a different filter or create a new record.</td></tr>`}</tbody></table></div>`}
function tr(...cells){return `<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`}
function field(n,label,value='',type='text',extra=''){return `<div class="field"><label for="f_${n}">${esc(label)}</label><input id="f_${n}" name="${esc(n)}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function select(n,label,opts,selected='',extra=''){return `<div class="field"><label for="f_${n}">${esc(label)}</label><select id="f_${n}" name="${esc(n)}" ${extra}>${opts.map(o=>{let a=Array.isArray(o)?o:[o,o];return `<option value="${esc(a[0])}" ${String(a[0])===String(selected)?'selected':''}>${esc(a[1])}</option>`}).join('')}</select></div>`}
function textarea(n,label,value=''){return `<div class="field wide"><label for="f_${n}">${esc(label)}</label><textarea id="f_${n}" name="${esc(n)}">${esc(value)}</textarea></div>`}
function form(type,contents,submit='Save',hidden=''){return `<form data-form="${type}">${hidden}${`<div class="form-grid">${contents}</div>`}<div class="form-actions"><button class="btn" type="button" data-action="close">Cancel</button><button class="btn primary" type="submit">${submit}</button></div></form>`}
function popup(title,content){$('#modal-contents').innerHTML=`<div class="modal-pad"><div class="modal-top"><h2 id="modal-title">${esc(title)}</h2><button class="close" type="button" data-action="close" aria-label="Close dialog">✕</button></div>${content}</div>`;$('#modal').showModal()}
function close(){if($('#modal').open)$('#modal').close()}
function kpi(label,val,detail=''){return `<div class="card kpi"><div class="k-label">${esc(label)}</div><div class="k-num">${esc(val)}</div><div class="k-hint">${esc(detail)}</div></div>`}
function empty(label){return `<div class="empty"><div class="big">◎</div>${esc(label)}</div>`}
function allow(pg){return (NAV[role]||[]).some(n=>n[0]===pg)}
function go(pg){if(!allow(pg)){toast('This area is not assigned to your persona.');return}page=pg;ui.search='';ui.filter='All';ui.category='All';render();window.scrollTo(0,0)}
function myreqs(){return db.requisitions.filter(r=>role!=='requester'||r.owner==='requester')}
function myorders(){return db.orders.filter(p=>role!=='requester'||p.owner==='requester')}
function myinvoices(){return db.invoices.filter(i=>role!=='supplier'||byid('orders',i.po)?.supplier==='S1')}
function notifications(){return [
 ...(role==='approver'?db.requisitions.filter(r=>r.status==='Pending approval').map(r=>({title:r.id+' needs approval',page:'approvals'})):[]),
 ...(role==='procurement'?db.requisitions.filter(r=>r.status==='Approved'||r.status==='Escalated').map(r=>({title:r.id+' awaits purchasing',page:'requisitions'})):[]),
 ...(role==='supplier'?db.orders.filter(p=>p.supplier==='S1'&&p.status==='Issued').map(p=>({title:p.id+' awaits supplier acceptance',page:'supplierorders'})):[]),
 ...(role==='finance'?db.invoices.filter(i=>i.status==='Submitted'||i.status==='Matched').map(i=>({title:i.id+' awaiting AP action',page:'invoices'})):[]),
 ...(role==='admin'?db.products.filter(p=>p.status==='Review').map(p=>({title:p.sku+' awaits catalog moderation',page:'catalog'})):[])
 ]}
function login(){let cards=Object.entries(PEOPLE).map(([id,p])=>`<button class="persona" data-action="login" data-id="${id}" aria-label="Sign in as ${esc(p.title)}"><span class="pi">${p.icon}</span><span><b>${esc(p.title)}</b><small>${esc(byid('users',id)?.name||p.name)} · ${esc(p.org)}</small></span></button>`).join('');$('#app').innerHTML=`<div class="login-shell"><div class="login-left"><div class="topnote">SOURCEWELL  /  DIGITAL PROCUREMENT</div><h1>One procurement experience. Six purpose-built workspaces.</h1><p>From request to approval, purchase order, supplier shipment, receiving and three-way financial match — a connected demonstration for Sourcewell RFP #110426.</p><div class="login-feature"><div>✓ &nbsp; Five connected procurement modules</div><div>✓ &nbsp; Real, editable local demo records</div><div>✓ &nbsp; Role-aware navigation &amp; transaction controls</div><div>✓ &nbsp; Four operational-goods categories</div></div><div class="orb"><img src="assets/sourcewell_rfp_logo.jpg" alt="Sourcewell logo from the official buyer-provided RFP"></div><p class="tiny" style="margin-top:12px">Independent demonstration concept. Sourcewell is not the operator or endorser of this mock environment.</p></div><div class="login-right"><div class="eyebrow">DEMONSTRATION ENVIRONMENT / NOT PRODUCTION</div><div class="heading"><div><h2>Choose your workspace</h2><p class="sub">Select a fictional user to explore their permissions, home page and workflows.</p></div><span class="badge purple">6 personas</span></div><div class="persona-grid">${cards}</div><div class="sso"><h4>◈ &nbsp;Corporate SSO — simulated</h4><p>Single-sign-on and multi-profile access are demonstrated locally. No identity-provider credentials, external authentication or personal information are transmitted.</p><div class="actions">${button('sso','Continue with demo SSO','primary')}</div></div><div class="notice warn" style="margin-top:20px">All products, suppliers, prices, tax certificates, inventory, transaction records and integration responses are fictional. RFP #110426 is a solicitation identifier, <b>not an awarded Sourcewell contract</b>.</div></div></div>`}
function shell(){let p=PEOPLE[role],items=NAV[role];$('#app').innerHTML=`<div class="app"><header class="topbar"><div class="brand" data-page="home" role="button" tabindex="0"><img class="brand-logo" src="assets/sourcewell_rfp_logo.jpg" alt="Sourcewell official mark from RFP #110426"><div><b>Sourcewell</b><small>Digital Procurement Experience</small></div></div><div class="top-search"><span>⌕</span><input type="search" id="global-search" placeholder="Search requisitions, orders, products…" autocomplete="off" aria-label="Search all my records"></div><div class="header-end"><span class="header-pill">SOURCEWELL · RFP 110426</span><button class="header-ghost" data-action="notices" title="Notifications" aria-label="View notifications">♧ <span id="notice-count">${notifications().length}</span></button><button class="user-button" data-action="switch" aria-label="Switch role"><span class="av">${esc(p.name.split(' ').map(x=>x[0]).join(''))}</span><span>${esc(p.name)}<small>${esc(p.title)} ▾</small></span></button></div></header><div class="body-layout"><aside><div class="section-label">My workspace</div>${items.map(([id,label,ic])=>`<button class="nav ${page===id?'active':''}" data-page="${id}" title="${esc(label)}"><span class="symbol">${ic}</span>${esc(label)}${(id==='approvals'||id==='cart')?`<span class="count">${id==='cart'?db.cart.length:db.requisitions.filter(r=>r.status==='Pending approval').length}</span>`:''}</button>`).join('')}<div class="spacer"></div><div class="footer-note"><b>Sourcewell #110426</b><br>Functional local prototype<br>Not a live procurement platform<br>Data saved only in this browser.</div></aside><main id="main"></main></div></div>`;$('#main').innerHTML=view();$('#notice-count').textContent=notifications().length}
function render(){if(!role)return login();if(!PEOPLE[role]||!byid('users',role)?.enabled){role='';sessionStorage.removeItem(LOGIN);return login()}if(!allow(page))page='home';shell()}
function view(){switch(page){case 'home':return home();case 'catalog':return catalog();case 'cart':return cart();case 'requisitions':return requisitions();case 'approvals':return approvals();case 'orders':return orders();case 'supplierorders':return supplierorders();case 'receiving':return receiving();case 'invoices':return invoices();case 'contracts':return contracts();case 'suppliers':return suppliers();case 'budgets':return budgets();case 'reports':return reports();case 'audit':return audittable();case 'users':return users();case 'policies':return policies();case 'integrations':return integrations();case 'tax':return tax();case 'profile':return profile();default:return home()}}
function home(){let p=PEOPLE[role],r=db.requisitions,orders=db.orders,inv=db.invoices;let metrics,quick,headline,secondary;
 if(role==='requester'){metrics=[['My requests',r.filter(x=>x.owner===role).length,'Across all statuses'],['Awaiting approval',r.filter(x=>x.owner===role&&x.status==='Pending approval').length,'In manager queue'],['Active orders',orders.filter(x=>x.owner===role&&!x.paid).length,'Track my deliveries'],['Basket items',db.cart.length,'Ready to requisition']];quick=[['Browse approved catalog','catalog'],['Review my basket','cart'],['Track my requests','requisitions']];headline='My recent requisitions';secondary=requisitionTable(myreqs().slice(0,4))}
 else if(role==='approver'){metrics=[['Pending approvals',r.filter(x=>x.status==='Pending approval').length,'Require department decision'],['Approved requests',r.filter(x=>x.status==='Approved').length,'Waiting for purchasing'],['Team budget remaining',money(db.budgets[0].limit-db.budgets[0].spent),'Facilities & Administration'],['Policy threshold',money(db.policies.approvalLimit),'Above this escalates']];quick=[['Open approval inbox','approvals'],['Check department budget','budgets'],['Review insights','reports']];headline='Approvals assigned to me';secondary=requisitionTable(r.filter(x=>x.status==='Pending approval').slice(0,5))}
 else if(role==='procurement'){metrics=[['Purchase orders',orders.length,'Current demo records'],['Ready to order',r.filter(x=>x.status==='Approved'||x.status==='Escalated').length,'Convert to issued POs'],['Awaiting receiving',orders.filter(x=>x.status==='Shipped'||x.status==='Part Received').length,'Incoming deliveries'],['Managed suppliers',db.suppliers.filter(s=>s.status==='Approved').length,'Sample seller directory']];quick=[['Review requisitions','requisitions'],['Open purchasing orders','orders'],['View supplier governance','suppliers']];headline='Latest procurement activity';secondary=orderTable(orders.slice(0,5))}
 else if(role==='supplier'){let sorders=orders.filter(x=>x.supplier==='S1');metrics=[['Purchase orders',sorders.length,'Assigned to sample supplier'],['Orders to confirm',sorders.filter(x=>x.status==='Issued').length,'Awaiting acknowledgement'],['Shipments in transit',sorders.filter(x=>x.status==='Shipped').length,'Update delivery information'],['My catalog items',db.products.filter(x=>x.supplier==='S1').length,'Manage product proposals']];quick=[['Review incoming orders','supplierorders'],['Maintain product catalog','catalog'],['Send invoice','invoices']];headline='Incoming purchase orders';secondary=orderTable(sorders.slice(0,5))}
 else if(role==='finance'){metrics=[['Open invoices',inv.filter(x=>!['Paid','Rejected'].includes(x.status)).length,'For matching / posting'],['Paid invoices',inv.filter(x=>x.status==='Paid').length,'Reconciled records'],['PO commitments',money(orders.reduce((a,p)=>a+p.total,0)),'Fictional totals'],['Available budgets',money(db.budgets.reduce((a,b)=>a+b.limit-b.spent,0)),'Across three sample cost centers']];quick=[['Open AP workbench','invoices'],['View budget controls','budgets'],['Run analytics','reports']];headline='Accounts payable pipeline';secondary=invoiceTable(inv.slice(0,5))}
 else{metrics=[['Demo users',db.users.filter(u=>u.enabled).length,'Six initial personas'],['Review catalog items',db.products.filter(x=>x.status==='Review').length,'Await moderation'],['Integration jobs',db.integrations.length,'Simulated connectors'],['Audit events',db.audit.length,'Local audit records']];quick=[['Manage identities','users'],['Configure approval policy','policies'],['Run integration jobs','integrations']];headline='Recent audit events';secondary=auditRows(db.audit.slice(0,6))}
 let activity=db.audit.slice(0,5).map(l=>`<li><div><b>${esc(l.action)} · ${esc(l.subject)}</b><span class="muted tiny">${esc(byid('users',l.by)?.name||l.by)} · ${esc(l.time)}</span></div></li>`).join('');return `<div class="hero"><div><div style="font-size:10px;letter-spacing:2px;color:#b8dced;font-weight:800;margin-bottom:10px">WELCOME BACK · ${esc(p.title).toUpperCase()}</div><h2>${esc(p.home)}</h2><p>${esc(p.desc)} All changes persist across persona switches and browser refreshes.</p><div class="actions">${pgbutton(quick[0][1],quick[0][0],'')}${button('switch','Switch persona','')}</div></div><div class="hero-round">${p.icon}</div></div><div class="grid four">${metrics.map(x=>kpi(...x)).join('')}</div><div class="grid two" style="margin-top:17px"><div class="stack">${box(headline,secondary,pgbutton(quick[0][1],'Open workspace','sm'))}${box('Quick access',`<div class="grid" style="gap:9px">${quick.map(([x,y])=>`<button class="btn" data-page="${y}" style="text-align:left">↗ &nbsp;${esc(x)}</button>`).join('')}</div>`)}</div><div class="stack">${box('Activity timeline',`<ul class="timeline">${activity}</ul>`,pgbutton(role==='requester'?'requisitions':role==='approver'?'approvals':role==='supplier'?'supplierorders':role==='finance'?'invoices':'audit','More details','sm'))}<div class="notice warn"><b>Demonstration only.</b> No real awarded Sourcewell contract, supplier stock, tax verification, corporate SSO or ERP exchange is represented here. All entries are fictitious and editable.</div></div></div>`}
function reqTotal(r){return r.items.reduce((a,x)=>a+(x.price??prod(x.product).price)*x.qty,0)}
function requisitionTable(arr){return table(['Requisition','Purpose / owner','Department','Total','Status','Action'],arr.map(r=>tr(`<b class="cell-title">${r.id}</b><br><span class="tiny muted">${esc(r.created)}</span>`,`${esc(r.purpose)}<br><span class="muted tiny">${esc(byid('users',r.owner)?.name||r.owner)}</span>`,esc(dept(r.department)),money(r.total),status(r.status),button('req-detail','View','sm',r.id))))}
function orderTable(arr){return table(['Purchase order','Seller','Amount','Fulfillment','Payment','Action'],arr.map(p=>tr(`<b class="cell-title">${p.id}</b><br><span class="muted tiny">${p.request}</span>`,esc(sup(p.supplier)),money(p.total),status(p.status),p.paid?status('Paid'):status('Open'),button('po-detail','Open','sm',p.id))))}
function invoiceTable(arr){return table(['Invoice','Purchase order','Seller','Amount','Status','Action'],arr.map(i=>tr(`<b class="cell-title">${i.id}</b><br><span class="tiny muted">${esc(i.number)}</span>`,esc(i.po),esc(sup(i.supplier)),money(i.amount),status(i.status),button('invoice-detail','Inspect','sm',i.id))))}
function auditRows(arr){return table(['Time','Actor','Event','Reference','Detail'],arr.map(x=>tr(`<span class="tiny">${esc(x.time)}</span>`,esc(PEOPLE[x.by]?.name||x.by),`<b>${esc(x.action)}</b>`,esc(x.subject),esc(x.detail))))}
function filterText(list,cb){let q=ui.search.toLowerCase().trim();return list.filter(x=>!q||cb(x).toLowerCase().includes(q))}
function searchControls(placeholder='Search records…',right=''){return `<div class="toolbar"><input class="search-field" id="page-search" value="${esc(ui.search)}" placeholder="${esc(placeholder)}" aria-label="Filter current table">${right}</div>`}
function catalog(){let own=role==='supplier',canShop=role==='requester',products=filterText(db.products.filter(p=>!own||p.supplier==='S1').filter(p=>ui.category==='All'||p.category===ui.category).filter(p=>own||role==='procurement'||role==='admin'||p.status==='Active'),p=>p.name+' '+p.category+' '+p.sku);let actions=role==='supplier'?button('product-add','Propose new item','primary'):role==='procurement'||role==='admin'?button('product-add','Add catalog item','primary'):pgbutton('cart',`Basket (${db.cart.reduce((s,x)=>s+x.qty,0)})`,'primary');let panels=`<div class="toolbar"><input class="search-field" id="page-search" value="${esc(ui.search)}" placeholder="Search products or SKUs" aria-label="Search catalog">${`<select class="select" id="category-filter" aria-label="Filter category">${['All',...CATS].map(c=>`<option ${ui.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`}<span class="muted tiny">${products.length} matching products</span></div>`;
 return head(own?'My supplier catalog':canShop?'Operational goods marketplace':'Catalog administration',own?'Propose catalog items for procurement moderation.':canShop?'Browse fictional operational goods across all four requested categories.':'Review category availability and moderate supplier product records.',actions)+`<div class="notice warn" style="margin-bottom:16px">Catalog entries, prices, seller descriptions and stock counts are <b>synthetic demo data</b>, not evidence of authorized product distribution, real inventory or awarded Sourcewell contract pricing.</div>${panels}<div class="grid four">${products.map(p=>`<article class="product"><div class="product-icon">${CATICON[p.category]||'▣'}</div><div class="tiny muted">${esc(p.category)} · ${esc(p.sku)}</div><div class="name">${esc(p.name)}</div><div class="meta">${esc(sup(p.supplier))} · per ${esc(p.unit)} · Demo stock ${int(p.stock)}</div><div class="price">${money(p.price)}</div><div class="actions">${status(p.status)} ${canShop?`<button class="btn primary sm" data-action="add-cart" data-id="${p.id}">+ Add</button>`:role==='supplier'?button('product-edit','Edit','sm',p.id):p.status==='Review'?button('product-approve','Approve','sm primary',p.id):button('product-edit','Edit','sm',p.id)}</div></article>`).join('')||empty('No products available for this filter.')}</div>`}
function cart(){let rows=db.cart.map(x=>{let p=prod(x.product);return tr(`<b class="cell-title">${esc(p.name)}</b><br><span class="tiny muted">${esc(p.sku)}</span>`,esc(sup(p.supplier)),`<input type="number" class="search-field" style="width:80px;min-width:80px" min="1" max="999" data-qty="${esc(p.id)}" value="${x.qty}" aria-label="Quantity for ${esc(p.name)}">`,money(p.price),money(p.price*x.qty),button('remove-cart','Remove','sm red',p.id))});let total=db.cart.reduce((s,x)=>s+prod(x.product).price*x.qty,0);return head('My purchasing basket','Changing a quantity recalculates totals immediately. All amounts are illustrative.',button('clear-cart','Clear basket',''))+box('Selected supplies',table(['Item','Seller','Quantity','Unit price','Line total',''],rows))+`<div class="grid two" style="margin-top:16px"><div class="notice">Departments and approval policy are applied when the requisition is submitted. Buyers may combine items from multiple suppliers; purchasing creates supplier-specific orders.</div>${box('Basket summary',`<div class="kv"><span>Line items</span><strong>${db.cart.length}</strong></div><div class="kv"><span>Subtotal</span><strong>${money(total)}</strong></div><div class="kv"><span>Real-time policy limit</span><strong>${money(db.policies.approvalLimit)}</strong></div><div style="margin-top:17px">${button('submit-cart','Create purchase requisition','primary','',db.cart.length?'':'disabled')}</div>`)}</div>`}
function requisitions(){let arr=filterText(myreqs().filter(r=>ui.filter==='All'||r.status===ui.filter),r=>r.id+' '+r.purpose+' '+dept(r.department));let list=['All','Pending approval','Approved','Escalated','Ordered','Rejected'];return head(role==='requester'?'My purchase requisitions':'Requisition management','Each requisition retains request details, department, approval status and transaction lineage.')+searchControls('Search requisition or department',`<select class="select" id="status-filter">${list.map(s=>`<option ${s===ui.filter?'selected':''}>${s}</option>`).join('')}</select>`)+box(`${arr.length} requisitions`,requisitionTable(arr))}
function approvals(){let arr=filterText(db.requisitions.filter(r=>r.status==='Pending approval'),r=>r.purpose+' '+r.id);return head('Department approval inbox','Approve legitimate spend, reject with a reason or escalate orders over the configured authority limit.')+searchControls('Search pending approvals')+box('Requires my decision',table(['Request','Department','Purpose','Value','Approval rule','Decision'],arr.map(r=>tr(r.id,esc(dept(r.department)),esc(r.purpose),money(r.total),r.total>db.policies.approvalLimit?status('Escalate above limit'):status('Within authority'),`${button('approve','Approve','sm primary',r.id)} ${button('reject','Reject','sm red',r.id)} ${button('req-detail','View','sm',r.id)}`))))}
function orders(){let arr=filterText(myorders().filter(p=>ui.filter==='All'||p.status===ui.filter),p=>p.id+' '+sup(p.supplier)+' '+p.request);return head(role==='finance'?'Purchase commitments':role==='requester'?'My purchase orders':'Purchase order workbench','Every PO links to its requisition, supplier, delivery, receiving and finance documents.',role==='procurement'?pgbutton('requisitions','Find approved requisitions','primary'):'')+searchControls('Search purchase order or seller',`<select class="select" id="status-filter">${['All','Issued','Accepted','Shipped','Part Received','Received'].map(s=>`<option ${ui.filter===s?'selected':''}>${s}</option>`).join('')}</select>`)+box(`${arr.length} purchase orders`,orderTable(arr))}
function supplierorders(){let arr=filterText(db.orders.filter(p=>p.supplier==='S1'),p=>p.id+' '+p.status);return head('Supplier order management','Acknowledge an incoming PO and enter carrier / tracking details. Fulfillment is simulated, not dispatched.')+searchControls('Search assigned purchase orders')+box('Orders routed to Sample Office Supply Co.',orderTable(arr))}
function receiving(){let arr=db.orders.filter(p=>['Shipped','Part Received','Received'].includes(p.status));return head('Goods receiving','Record accepted units against each simulated order; receipts flow into the finance matching rule.')+box('Receiving queue',table(['PO','Seller','Order qty','Received','Status','Action'],arr.map(p=>tr(p.id,esc(sup(p.supplier)),int(p.items.reduce((a,b)=>a+b.qty,0)),int(p.received||0),status(p.status),button('po-detail','Receive / inspect','sm',p.id)))))+`<div style="margin-top:17px">${box('Receipt register',table(['Receipt','Order','Quantity','Accepted by','Date'],db.receipts.map(x=>tr(x.id,x.po,int(x.qty),esc(PEOPLE[x.by]?.name||x.by),esc(x.created)))))}</div>`}
function invoices(){let arr=filterText(myinvoices(),x=>x.id+' '+x.number+' '+x.po);let canCreate=role==='supplier'||role==='finance';return head(role==='supplier'?'Supplier invoices':'Accounts payable workbench','Invoice matching uses purchase-order quantity, goods receipt, approved seller and monetary checks.',canCreate?button('invoice-new','Create invoice','primary'):'')+searchControls('Search invoice / PO reference')+box('Invoice register',invoiceTable(arr))+`<div class="notice" style="margin-top:16px"><b>Three-way match:</b> ordered quantity vs accepted quantity vs invoice value. Payment is a local status event and does not transfer funds.</div>`}
function contracts(){let arr=filterText(db.contracts,c=>c.name+' '+c.id);return head('Enterprise contract registry','Illustrative contract metadata, value utilization and expiration. RFP 110426 is not an awarded contract.',button('contract-new','New contract','primary'))+searchControls('Search contracts')+box('Contract portfolio',table(['Contract','Supplier','Ceiling','Utilized','Status','Expiry','Action'],arr.map(c=>tr(`<b class="cell-title">${esc(c.id)}</b><br>${esc(c.name)}`,esc(sup(c.supplier)),money(c.ceiling),`${money(c.spent)}<div class="progress"><span style="width:${Math.min(100,Math.round(100*c.spent/Math.max(1,c.ceiling)))}%"></span></div>`,status(c.status),esc(c.expires),`${button('contract-edit','Edit','sm',c.id)}`))))}
function suppliers(){let arr=filterText(db.suppliers,s=>s.name+' '+s.category);return head('Supplier governance','Seller status, region, category and diversity verification are tracked separately from the mock marketplace.',button('supplier-new','Add sample seller','primary'))+searchControls('Search sellers or categories')+box('Seller directory',table(['Seller of record','Category / geography','Diversity status','Governance','Action'],arr.map(s=>tr(`<b>${esc(s.name)}</b><br><span class="tiny muted">${esc(s.contact)}</span>`,`${esc(s.category)}<br><span class="tiny muted">${esc(s.region)}</span>`,status(s.diversity),status(s.status),`${button('supplier-edit','Edit','sm',s.id)} ${button('supplier-toggle',s.status==='Approved'?'Suspend':'Approve',s.status==='Approved'?'sm red':'sm primary',s.id)}`))))}
function budgets(){return head('Budgetary control','Live sample cost-center budgets; procurement approvals reserve amounts in the local demo.')+`<div class="grid three">${db.budgets.map(b=>`<div class="card"><span class="tiny muted">${esc(b.id)}</span><h3 style="margin-top:9px">${esc(b.name)}</h3><div class="k-num" style="font-size:23px;font-weight:800;margin:12px 0">${money(b.limit-b.spent)}</div><div class="progress"><span style="width:${Math.min(100,b.spent/b.limit*100)}%"></span></div><p class="tiny muted" style="margin:11px 0">${money(b.spent)} committed of ${money(b.limit)} budget</p>${role==='finance'?button('budget-edit','Adjust budget','sm',b.id):''}</div>`).join('')}</div>`}
function reports(){let goods=CATS.map(c=>({name:c,sum:db.orders.reduce((a,o)=>a+o.items.reduce((b,i)=>b+(prod(i.product).category===c?i.price*i.qty:0),0),0)}));let total=goods.reduce((s,x)=>s+x.sum,0);let max=Math.max(1,...goods.map(x=>x.sum));let counts=db.requisitions.length,pend=db.requisitions.filter(x=>x.status==='Pending approval').length;return head('Procurement insights','Interactive reports computed from local transactions, not hard-coded screenshots.',`${button('export-spend','Export spend CSV','')} ${button('export-audit','Export audit CSV','')}`)+`<div class="grid four">${kpi('Committed PO value',money(db.orders.reduce((a,p)=>a+p.total,0)),'All recorded orders')}${kpi('Category coverage','4 / 4','Synthetic catalog categories')}${kpi('Pending approvals',int(pend),`Of ${counts} requisitions`)}${kpi('Invoices paid',money(db.invoices.filter(i=>i.status==='Paid').reduce((a,i)=>a+i.amount,0)),'Demo journal postings')}</div><div class="grid two" style="margin-top:17px">${box('Spend by operational-goods category',`<div class="bar-chart">${goods.map(c=>`<div class="bar-line"><span>${esc(c.name)}</span><div class="track"><div class="fill" style="width:${c.sum/max*100}%"></div></div><b>${money(c.sum)}</b></div>`).join('')}</div><div class="divider"></div><b>Total ordered goods (excl. sample tax/freight) · ${money(total)}</b>`)}${box('Seller participation',table(['Seller','PO count','Committed value'],db.suppliers.map(s=>tr(esc(s.name),db.orders.filter(x=>x.supplier===s.id).length,money(db.orders.filter(x=>x.supplier===s.id).reduce((a,p)=>a+p.total,0))))))}</div><div style="margin-top:17px">${box('Responsible sourcing & audit indicators',`<div class="grid three">${[['Supplier diversity records',db.suppliers.filter(s=>s.diversity!=='Unverified').length,'Self-attestation / certifications not independently verified'],['Approved sample suppliers',db.suppliers.filter(s=>s.status==='Approved').length,'Illustrative seller governance states'],['Local audit events',db.audit.length,'Exportable demo events only']].map(x=>`<div class="report-tile"><div class="tiny muted">${esc(x[0])}</div><h2 style="margin:9px 0 5px">${x[1]}</h2><div class="tiny muted">${esc(x[2])}</div></div>`).join('')}</div>`)}</div>`}
function audittable(){let arr=filterText(db.audit,a=>a.by+' '+a.action+' '+a.subject+' '+a.detail);return head('Transaction audit center','Timestamped local events linked to requisitions, POs, receipts, invoices, catalog and administration.',`${button('export-audit','Export audit CSV','')} ${button('export-json','Backup demo JSON','')} ${role==='admin'?button('reset','Reset all demo data','warn'):''}`)+searchControls('Search audit actions or references')+box(`${arr.length} log records`,auditRows(arr))}
function users(){return head('Identity & role access','Enable/disable demo profiles, inspect role separation and simulate SSO entry. No directory integration exists.',button('sso','Try simulated SSO','primary'))+box('Six-role identity directory',table(['Demo profile','Organization','Sign-in ID','Role','Access','Action'],db.users.map(u=>tr(`<b>${esc(u.name)}</b>`,esc(PEOPLE[u.id]?.org||''),`<code>${esc(u.email)}</code>`,esc(u.title),status(u.enabled?'Active':'Suspended'),u.id==='admin'?'<span class="muted">Protected admin</span>':button('user-toggle',u.enabled?'Disable':'Enable',u.enabled?'sm red':'sm primary',u.id)))))+`<div class="notice" style="margin-top:17px">Role navigation and in-app transactions are checked at the client-side action boundary. This is <b>not</b> security equivalent to a server-authorized production tenancy.</div>`}
function policies(){let p=db.policies;return head('Approval & spend policies','Configured thresholds alter new approval routes; tax is explicitly a fictional calculation.',button('policy-edit','Edit purchasing policy','primary'))+`<div class="grid three">${kpi('Manager approval ceiling',money(p.approvalLimit),'Requests above ceiling escalate to procurement')}${kpi('Illustrative sales tax',`${p.taxRate}%`,'Applied only if demo certificate is unvalidated')}${kpi('Invoice tolerance',money(p.variance),'Absolute variance allowed in 3-way match')}</div><div style="margin-top:17px">${box('Approval control sequence',`<div class="steps"><span class="step">Requester submits</span><span>›</span><span class="step">Manager reviews</span><span>›</span><span class="step">Procurement escalation if needed</span><span>›</span><span class="step">PO issued</span></div><div class="notice">Segregation of duties: a requester cannot self-approve, suppliers cannot receive goods for buyers, and only Finance can post payment.</div>`)}</div>`}
function integrations(){return head('ERP & integration console','Runs are simulated and auditable. No corporate SSO, external ERP, suppliers or punchout sites are contacted.')+`<div class="grid three">${db.integrations.map(j=>`<div class="card"><div class="tiny muted">CONNECTION · ${esc(j.id)}</div><h3 style="margin-top:10px">${esc(j.name)}</h3>${status(j.status)}<div class="divider"></div><div class="tiny muted">Last execution: ${esc(j.last)}</div><div style="margin-top:16px">${button('integration-run','Run simulated sync','sm primary',j.id)}</div></div>`).join('')}</div>${box('Integration treatment',`<div class="notice warn">Real punchout, OAuth/OIDC, finance posting, payment rails, courier tracking and vendor inventory require authorized production endpoints. Here, the visible simulated sync produces an internal audit event only.</div>`)}`}
function tax(){return head('Tax-exemption controls','Maintain mock certificate references. Verification is manual and illustrative, not a tax calculation or legal opinion.',button('tax-new','Add certificate','primary'))+box('Certificate register',table(['Certificate','Entity','Expires','Validation','Action'],db.tax.map(t=>tr(`<b>${esc(t.certificate)}</b>`,esc(t.entity),esc(t.expiry),status(t.status),button('tax-toggle',t.status==='Validated (demo)'?'Mark unverified':'Validate in demo', 'sm',t.id)))))+`<div class="notice warn" style="margin-top:17px">"Validated (demo)" means a local user pressed the demo button; the underlying exemption certificate has not been independently verified.</div>`}
function profile(){let me=byid('users',role);return head('My account','Edit fictional profile details for the active role. Changes persist in this browser.',button('profile-edit','Edit profile','primary'))+`<div class="grid two">${box('Persona identity',`<div class="kv"><span>Display name</span><strong>${esc(me.name)}</strong></div><div class="kv"><span>Role</span><strong>${esc(me.title)}</strong></div><div class="kv"><span>Organization</span><strong>${esc(PEOPLE[role].org)}</strong></div><div class="kv"><span>Username</span><strong>${esc(me.email)}</strong></div><div class="kv"><span>Authentication</span><strong>Simulated corporate SSO</strong></div>`)}${box('Session & privacy',`<p class="muted">This user session exists only in your active browser tab. Records are stored using localStorage, without a hosted backend.</p>${button('switch','Switch persona','primary')} ${button('logout','Sign out','')}`)}</div>`}
function requestDetails(id){let r=byid('requisitions',id);if(!r)return;let b=byid('budgets',r.department);let lines=table(['Item','Supplier','Quantity','Unit price','Value'],r.items.map(x=>tr(esc(prod(x.product).name),esc(sup(prod(x.product).supplier)),int(x.qty),money(x.price??prod(x.product).price),money(x.qty*(x.price??prod(x.product).price)))));let actions='';if(role==='approver'&&r.status==='Pending approval')actions=`${button('approve','Approve','primary',r.id)} ${button('reject','Reject','red',r.id)}`;if(role==='procurement'&&r.status==='Escalated')actions+=button('escalation-approve','Authorize escalation','primary',r.id);if(role==='procurement'&&r.status==='Approved')actions+=button('create-po','Issue supplier POs','primary',r.id);popup(`Requisition ${r.id}`,`<div class="grid two"><div><div class="kv"><span>Purpose</span><strong>${esc(r.purpose)}</strong></div><div class="kv"><span>Requested by</span><strong>${esc(byid('users',r.owner)?.name||r.owner)}</strong></div><div class="kv"><span>Cost center</span><strong>${esc(dept(r.department))}</strong></div><div class="kv"><span>Status</span>${status(r.status)}</div></div><div><div class="kv"><span>Request value</span><strong>${money(r.total)}</strong></div><div class="kv"><span>Budget available</span><strong>${money(b.limit-b.spent)}</strong></div><div class="kv"><span>Authority limit</span><strong>${money(db.policies.approvalLimit)}</strong></div><div class="kv"><span>Audit reference</span><strong>${r.id}</strong></div></div></div><div class="divider"></div>${lines}<p class="muted tiny" style="margin-top:14px">${esc(r.notes||'No further notes')}</p><div class="form-actions">${actions}${button('close','Close')}</div>`)}
function poDetails(id){let p=byid('orders',id);if(!p)return;let qty=p.items.reduce((a,x)=>a+x.qty,0),remaining=Math.max(0,qty-(p.received||0)),isSupplier=role==='supplier';let lines=table(['Item / SKU','Qty','Price','Amount'],p.items.map(x=>tr(`<b>${esc(prod(x.product).name)}</b><br><span class="tiny muted">${esc(prod(x.product).sku)}</span>`,int(x.qty),money(x.price),money(x.price*x.qty))));let c='';if(isSupplier&&p.supplier==='S1'&&p.status==='Issued')c+=button('po-accept','Acknowledge order','primary',id);if(isSupplier&&p.supplier==='S1'&&p.status==='Accepted')c+=button('po-ship','Create shipment','primary',id);if(role==='procurement'&&['Shipped','Part Received'].includes(p.status)&&remaining>0)c+=button('po-receive',`Record receipt (${remaining} remaining)`,'primary',id);if(role==='finance')c+=pgbutton('invoices','Open AP workbench','');let rec=db.receipts.filter(r=>r.po===id),invs=db.invoices.filter(i=>i.po===id);popup(`Purchase order ${id}`,`<div class="grid two"><div><div class="kv"><span>Requisition</span><strong>${esc(p.request)}</strong></div><div class="kv"><span>Supplier</span><strong>${esc(sup(p.supplier))}</strong></div><div class="kv"><span>Order status</span>${status(p.status)}</div><div class="kv"><span>Cost center</span><strong>${esc(dept(p.department))}</strong></div></div><div><div class="kv"><span>PO total</span><strong>${money(p.total)}</strong></div><div class="kv"><span>Goods received</span><strong>${p.received||0} / ${qty} units</strong></div><div class="kv"><span>Sales tax</span><strong>${money(p.taxAmount)} (illustrative)</strong></div><div class="kv"><span>Payment</span>${status(p.paid?'Paid':'Open')}</div></div></div><div class="divider"></div>${lines}<div class="grid two" style="margin-top:13px"><div class="report-tile"><h4>Shipment</h4><p class="tiny muted">Carrier: ${esc(p.carrier||'Not entered')}<br>Tracking: ${esc(p.tracking||'Awaiting supplier')}<br>Shipping fee: ${money(p.shipCost||0)}</p></div><div class="report-tile"><h4>Receiving & invoices</h4><p class="tiny muted">${rec.map(x=>`${x.id} · ${x.qty} units`).join('<br>')||'No goods receipts'}<br>${invs.map(x=>`${x.id} · ${x.status}`).join('<br>')||'No supplier invoice'}</p></div></div><div class="notice warn" style="margin-top:12px">${esc(p.contract||'RFP #110426 is not an awarded agreement.')} · no actual seller dispatch, tax validation or funds movement.</div><div class="form-actions">${c}${button('close','Close')}</div>`)}
function invoiceDetails(id){let i=byid('invoices',id);if(!i)return;let p=byid('orders',i.po),rec=p?db.receipts.filter(r=>r.po===p.id).reduce((a,r)=>a+r.qty,0):0,ordered=p?p.items.reduce((a,x)=>a+x.qty,0):0,expected=p?.total||0,eligible=p&&rec>=ordered&&Math.abs(expected-i.amount)<=db.policies.variance&&byid('suppliers',p.supplier)?.status==='Approved';let actions='';if(role==='finance'){if(i.status!=='Paid'){actions+=button('invoice-match','Run 3-way match', 'primary',id);actions+=button('invoice-edit','Correct invoice','',id)}if(i.status==='Matched')actions+=button('invoice-pay','Post demo payment','primary',id)}popup(`Invoice ${i.id}`,`<div class="grid two"><div><div class="kv"><span>Supplier invoice</span><strong>${esc(i.number)}</strong></div><div class="kv"><span>Purchase order</span><strong>${esc(i.po)}</strong></div><div class="kv"><span>Seller</span><strong>${esc(sup(i.supplier))}</strong></div><div class="kv"><span>Status</span>${status(i.status)}</div></div><div><div class="kv"><span>Invoice amount</span><strong>${money(i.amount)}</strong></div><div class="kv"><span>PO total</span><strong>${money(expected)}</strong></div><div class="kv"><span>Ordered qty</span><strong>${int(ordered)}</strong></div><div class="kv"><span>Accepted qty</span><strong>${int(rec)}</strong></div></div></div><div class="divider"></div><div class="steps"><span class="step ${p?'done':''}">PO exists</span> › <span class="step ${rec>=ordered?'done':'current'}">Received quantity</span> › <span class="step ${Math.abs(expected-i.amount)<=db.policies.variance?'done':'current'}">Invoice value</span> › <span class="step ${i.status==='Paid'?'done':'current'}">Payment</span></div><div class="notice ${eligible?'':'warn'}">${eligible?'All demo matching conditions are satisfied. Finance may record a matched status and demo payment.':'One or more matching conditions are not yet satisfied. The invoice must not be marked paid until corrected and received in full.'}</div><div class="form-actions">${actions}${button('close','Close')}</div>`)}
function openForm(type,id=''){let html='',title='';switch(type){
case 'requisition-submit':title='Submit purchase requisition';html=form('requisition-submit',select('department','Cost center',db.budgets.map(b=>[b.id,`${b.id} — ${b.name}`]),'DEP-100')+field('purpose','Business justification','Operational supplies replenishment','text','required maxlength="120"')+textarea('notes','Approver notes','Required for day-to-day operations.'),'Submit for approval');break;
case 'reject':title='Reject requisition';html=form('reject',textarea('reason','Reason for rejection','Please revise the purchase justification.'),'Reject requisition',`<input type="hidden" name="id" value="${esc(id)}">`);break;
case 'po-ship':title='Record supplier shipment';html=form('po-ship',field('carrier','Carrier name','Sample Delivery','text','required')+field('tracking','Tracking reference','DEMO-TRK-'+id,'text','required')+field('shipCost','Illustrative freight (CAD)',0,'number','min="0" step="0.01"'),'Mark as shipped',`<input type="hidden" name="id" value="${esc(id)}">`);break;
case 'po-receive':{let p=byid('orders',id),q=p.items.reduce((a,x)=>a+x.qty,0)-(p.received||0);title='Accept delivered goods';html=form('po-receive',field('qty',`Accepted quantity (maximum ${q})`,q,'number',`min="1" max="${q}" required`)+textarea('note','Condition / receiving note','Received and inspected in demo'),'Post goods receipt',`<input type="hidden" name="id" value="${esc(id)}">`);break}
case 'invoice-new':{let eligible=db.orders.filter(p=>(role!=='supplier'||p.supplier==='S1')&&p.status!=='Issued'&&!db.invoices.some(i=>i.po===p.id&&i.status!=='Rejected'));title='Create sample invoice';html=form('invoice-new',select('po','Purchase order',eligible.map(p=>[p.id,`${p.id} · ${sup(p.supplier)} · ${money(p.total)}`]),'','required')+field('number','Supplier invoice reference','SAMPLE-INV-'+(db.sequence+1),'text','required')+field('amount','Invoice total (CAD)',eligible[0]?.total||0,'number','min="0" step="0.01" required'),'Submit invoice');break}
case 'invoice-edit':{let i=byid('invoices',id);title='Correct supplier invoice';html=form('invoice-edit',field('amount','Corrected invoice value (CAD)',i.amount,'number','min="0" step="0.01" required')+field('number','Supplier invoice reference',i.number,'text','required'),'Save correction',`<input type="hidden" name="id" value="${esc(id)}">`);break}
case 'product-add':case 'product-edit':{let p=id?byid('products',id):null;title=p?'Edit catalog record':'Create catalog proposal';let sups=role==='supplier'?db.suppliers.filter(s=>s.id==='S1'):db.suppliers;html=form(type,field('name','Item description',p?.name||'','text','required maxlength="100"')+field('sku','Seller SKU / product code',p?.sku||'','text','required maxlength="40"')+select('category','Operational goods category',CATS,p?.category||CATS[0])+select('supplier','Seller of record',sups.map(s=>[s.id,s.name]),p?.supplier||sups[0]?.id)+field('price','Illustrative unit price (CAD)',p?.price||10,'number','min="0.01" step="0.01" required')+field('unit','Unit of measure',p?.unit||'each','text','required')+field('stock','Synthetic stock quantity',p?.stock??100,'number','min="0" step="1" required'),p?'Save catalog change':'Send catalog record',`<input type="hidden" name="id" value="${esc(id)}">`);break}
case 'supplier-new':case 'supplier-edit':{let s=id?byid('suppliers',id):null;title=s?'Edit seller governance':'Register sample seller';html=form(type,field('name','Seller name',s?.name||'','text','required')+select('category','Category',CATS,s?.category||CATS[0])+field('region','Delivery geography (sample only)',s?.region||'North America — illustrative','text','required')+field('contact','Demo contact email',s?.contact||'supplier@example.invalid','email','required')+select('diversity','Diversity certification status',['Unverified','Self-declared (demo)','Verified by admin (demo)'],s?.diversity||'Unverified'),'Save seller',`<input type="hidden" name="id" value="${esc(id)}">`);break}
case 'contract-new':case 'contract-edit':{let c=id?byid('contracts',id):null;title=c?'Edit sample contract':'Create sample contract';html=form(type,field('name','Agreement title',c?.name||'','text','required')+select('supplier','Seller',db.suppliers.map(s=>[s.id,s.name]),c?.supplier||'S1')+field('ceiling','Illustrative contract ceiling (CAD)',c?.ceiling||10000,'number','min="1" step="0.01" required')+field('expires','Expiration date',c?.expires||'2027-12-31','date','required')+select('status','Status',['Active','Pending','Expired'],c?.status||'Pending')+textarea('terms','Notes',c?.terms||'Sample agreement only; not an awarded Sourcewell contract.'),'Save agreement',`<input type="hidden" name="id" value="${esc(id)}">`);break}
case 'budget-edit':{let b=byid('budgets',id);title='Adjust cost-center allocation';html=form(type,field('limit','Authorized sample budget (CAD)',b.limit,'number',`min="${b.spent}" step="0.01" required`)+textarea('reason','Adjustment justification','Budget allocation revised for demonstration.'),'Save adjustment',`<input type="hidden" name="id" value="${esc(id)}">`);break}
case 'policy-edit':title='Configure spend controls';html=form(type,field('approvalLimit','Manager authority ceiling (CAD)',db.policies.approvalLimit,'number','min="0" step="0.01" required')+field('taxRate','Illustrative tax %',db.policies.taxRate,'number','min="0" max="25" step="0.1" required')+field('variance','Invoice match tolerance (CAD)',db.policies.variance,'number','min="0" step="0.01" required'),'Update controls');break;
case 'tax-new':title='Create demonstration certificate';html=form(type,field('entity','Entity','Sample Public Agency','text','required')+field('certificate','Certificate reference','DEMO-TAX-'+(db.sequence+1),'text','required')+field('expiry','Expiry date','2027-12-31','date','required'),'Add unverified certificate');break;
case 'profile-edit':{let u=byid('users',role);title='Edit my demo profile';html=form(type,field('name','Display name',u.name,'text','required')+field('email','Fictional sign-in ID',u.email,'email','required'),'Save profile');break}
}
if(html)popup(title,html)}
function checkRole(allowed){if(!allowed.includes(role)){toast('Permission denied for this persona.');return false}return true}
function run(action,id,el){switch(action){
case 'login':if(!byid('users',id)?.enabled){toast('This profile is disabled by the demo administrator.');return}role=id;sessionStorage.setItem(LOGIN,id);page='home';ui={search:'',category:'All',filter:'All',selected:'',notifications:false};render();toast(`Signed in as ${PEOPLE[role].title} (simulation)`);break;
case 'switch':case 'logout':role='';sessionStorage.removeItem(LOGIN);page='home';render();break;
case 'sso':popup('Simulated corporate SSO',`<p class="muted">Choose a test identity to complete a local SSO simulation. There is no external identity provider, MFA or token validation.</p><div class="grid two" style="margin-top:14px">${Object.entries(PEOPLE).filter(([id])=>byid('users',id)?.enabled).map(([id,p])=>`<button class="btn" data-action="login" data-id="${id}" style="white-space:normal;text-align:left">${p.icon} &nbsp; ${esc(p.title)}<br><span class="tiny muted">${esc(p.name)}</span></button>`).join('')}</div>`);break;
case 'close':close();break;
case 'notices':{let n=notifications();popup('My notifications',n.length?n.map(x=>`<div class="kv"><span>New activity</span><strong>${esc(x.title)} &nbsp; ${pgbutton(x.page,'Open','sm')}</strong></div>`).join(''):empty('No outstanding actions for this persona.'));break}
case 'add-cart':if(!checkRole(['requester']))return;{let p=prod(id);if(p.status!=='Active'||byid('suppliers',p.supplier)?.status!=='Approved'){toast('Item cannot be requested until catalog and seller are approved.');return}let c=db.cart.find(x=>x.product===id);if(c)c.qty++;else db.cart.push({product:id,qty:1});audit('BASKET UPDATED',id,`Added ${p.name}`);render();toast('Item added to your basket.')}break;
case 'remove-cart':if(!checkRole(['requester']))return;db.cart=db.cart.filter(x=>x.product!==id);audit('BASKET UPDATED',id,'Item removed');render();break;
case 'clear-cart':if(!checkRole(['requester']))return;db.cart=[];audit('BASKET CLEARED','Requester basket');render();break;
case 'submit-cart':if(!checkRole(['requester']))return;if(!db.cart.length){toast('Add catalog items first.');return}openForm('requisition-submit');break;
case 'req-detail':if(!checkRole(['requester','approver','procurement']))return;if(role==='requester'&&byid('requisitions',id)?.owner!==role)return;requestDetails(id);break;
case 'approve':if(!checkRole(['approver']))return;{let r=byid('requisitions',id);if(!r||r.status!=='Pending approval')return;let b=byid('budgets',r.department);if(b.limit-b.spent<r.total){toast('Insufficient sample budget. Ask Finance to adjust allocation.');return}if(r.total>db.policies.approvalLimit){r.status='Escalated';audit('REQUEST ESCALATED',r.id,`Value exceeds ${money(db.policies.approvalLimit)} authority`);toast('Escalated to Procurement because limit exceeded.')}else{r.status='Approved';b.spent+=r.total;audit('REQUEST APPROVED',r.id,'Approver authorized and budget reserved');toast(`${r.id} approved and budget reserved.`)}close();render()}break;
case 'escalation-approve':if(!checkRole(['procurement']))return;{let r=byid('requisitions',id);if(!r||r.status!=='Escalated')return;let b=byid('budgets',r.department);if(b.limit-b.spent<r.total){toast('Budget insufficient; Finance must adjust.');return}r.status='Approved';b.spent+=r.total;audit('ESCALATION AUTHORIZED',id,'Procurement authorized escalated spend');close();render()}break;
case 'reject':if(!checkRole(['approver']))return;openForm('reject',id);break;
case 'create-po':if(!checkRole(['procurement']))return;{let r=byid('requisitions',id);if(!r||r.status!=='Approved')return;if(r.items.some(x=>prod(x.product).status!=='Active'||byid('suppliers',prod(x.product).supplier)?.status!=='Approved'||prod(x.product).stock<x.qty)){toast('Supplier, catalog approval or synthetic stock availability prevents PO issuance.');return}let grouped={};for(let x of r.items){let s=prod(x.product).supplier;(grouped[s]??=[]).push({...x,price:x.price??prod(x.product).price})}let taxExempt=db.tax.some(t=>t.status==='Validated (demo)'&&t.expiry>=date());let projectedTax=Object.values(grouped).reduce((a,items)=>a+Math.round(items.reduce((v,x)=>v+x.qty*x.price,0)*(taxExempt?0:db.policies.taxRate)/100*100)/100,0);if(byid('budgets',r.department).limit-byid('budgets',r.department).spent<projectedTax){toast('Tax provision exceeds remaining sample budget. Ask Finance to revise allocation.');return}let ids=[];for(let [s,items] of Object.entries(grouped)){let amount=items.reduce((a,x)=>a+x.qty*x.price,0);let validated=db.tax.some(t=>t.status==='Validated (demo)'&&t.expiry>=date());let taxAmount=Math.round(amount*(validated?0:db.policies.taxRate)/100*100)/100;let contract=db.contracts.find(c=>c.supplier===s&&c.status==='Active');let po={id:next('PO'),request:id,owner:r.owner,supplier:s,department:r.department,items,total:Math.round((amount+taxAmount)*100)/100,shipCost:0,taxAmount,status:'Issued',tracking:'',carrier:'',created:date(),received:0,contract:contract?.id||'No supplier agreement linked (demo)',paid:false};db.orders.unshift(po);if(contract)contract.spent+=amount;ids.push(po.id)}r.items.forEach(x=>{prod(x.product).stock-=x.qty});let taxes=ids.reduce((a,id)=>a+byid('orders',id).taxAmount,0);byid('budgets',r.department).spent+=taxes;r.status='Ordered';audit('PO ISSUED',ids.join(', '),`Issued ${ids.length} supplier-specific orders against ${id}`);close();render();toast(`${ids.length} sample purchase order(s) issued.`)}break;
case 'po-detail':if(!checkRole(['requester','procurement','supplier','finance']))return;{let p=byid('orders',id);if(!p||role==='requester'&&p.owner!==role||role==='supplier'&&p.supplier!=='S1')return;poDetails(id)}break;
case 'po-accept':if(!checkRole(['supplier']))return;{let p=byid('orders',id);if(!p||p.supplier!=='S1'||p.status!=='Issued')return;p.status='Accepted';audit('PO ACKNOWLEDGED',id,'Sample supplier accepted PO');close();render();toast('Order accepted by sample supplier.')}break;
case 'po-ship':if(!checkRole(['supplier']))return;{let p=byid('orders',id);if(!p||p.supplier!=='S1'||p.status!=='Accepted')return;openForm('po-ship',id)}break;
case 'po-receive':if(!checkRole(['procurement']))return;{let p=byid('orders',id);if(!p||!['Shipped','Part Received'].includes(p.status))return;openForm('po-receive',id)}break;
case 'invoice-new':if(!checkRole(['supplier','finance']))return;{let opts=db.orders.filter(p=>(role!=='supplier'||p.supplier==='S1')&&p.status!=='Issued'&&!db.invoices.some(i=>i.po===p.id&&i.status!=='Rejected'));if(!opts.length){toast('No eligible un-invoiced purchase orders.');return}openForm('invoice-new')}break;
case 'invoice-detail':if(!checkRole(['finance','supplier']))return;if(role==='supplier'&&byid('invoices',id)?.supplier!=='S1')return;invoiceDetails(id);break;
case 'invoice-edit':if(!checkRole(['finance']))return;if(byid('invoices',id)?.status==='Paid')return;openForm('invoice-edit',id);break;
case 'invoice-match':if(!checkRole(['finance']))return;{let i=byid('invoices',id);if(!i||i.status==='Paid')return;let p=byid('orders',i.po);if(!p)return;let received=db.receipts.filter(r=>r.po===p.id).reduce((a,x)=>a+x.qty,0);let qty=p.items.reduce((a,x)=>a+x.qty,0);i.status=received>=qty&&Math.abs(i.amount-p.total)<=db.policies.variance&&byid('suppliers',p.supplier)?.status==='Approved'?'Matched':'Mismatch';audit('THREE WAY MATCH',id,`Result: ${i.status}; received ${received}/${qty}; invoiced ${money(i.amount)}; PO ${money(p.total)}`);close();render();toast(`3-way match result: ${i.status}`)}break;
case 'invoice-pay':if(!checkRole(['finance']))return;{let i=byid('invoices',id);if(!i||i.status!=='Matched')return;i.status='Paid';let p=byid('orders',i.po);if(p)p.paid=true;audit('PAYMENT POSTED (DEMO)',id,'No real money movement or bank connection');close();render();toast('Sample payment recorded (no money transferred).')}break;
case 'product-add':case 'product-edit':if(!checkRole(['supplier','procurement','admin']))return;{if(role==='supplier'&&id&&prod(id).supplier!=='S1')return;openForm(action,id)}break;
case 'product-approve':if(!checkRole(['procurement','admin']))return;{let p=byid('products',id);if(!p||p.status!=='Review')return;p.status='Active';audit('CATALOG APPROVED',p.sku,`Product published by ${role}`);render();toast('Product approved in sample catalog.')}break;
case 'supplier-new':case 'supplier-edit':if(!checkRole(['procurement','admin']))return;openForm(action,id);break;
case 'supplier-toggle':if(!checkRole(['procurement','admin']))return;{let s=byid('suppliers',id);if(!s)return;s.status=s.status==='Approved'?'Suspended':'Approved';audit('SELLER STATUS CHANGED',s.name,s.status);render();toast(`${s.name}: ${s.status}`)}break;
case 'contract-new':case 'contract-edit':if(!checkRole(['procurement','admin']))return;openForm(action,id);break;
case 'budget-edit':if(!checkRole(['finance']))return;openForm(action,id);break;
case 'policy-edit':if(!checkRole(['admin']))return;openForm(action);break;
case 'integration-run':if(!checkRole(['admin']))return;{let j=byid('integrations',id);if(!j)return;j.last=timestamp();j.status='Simulation completed';audit('SIMULATED INTEGRATION',id,`${j.name}; no external requests were sent`);render();toast(`${j.id}: local simulated sync complete.`)}break;
case 'tax-new':case 'tax-toggle':if(!checkRole(['admin']))return;if(action==='tax-new')openForm(action);else{let t=byid('tax',id);t.status=t.status==='Validated (demo)'?'Needs validation':'Validated (demo)';audit('DEMO TAX CONTROL',id,t.status);render()}break;
case 'user-toggle':if(!checkRole(['admin']))return;if(id==='admin')return;{let u=byid('users',id);u.enabled=!u.enabled;audit('ACCESS MODIFIED',id,u.enabled?'Enabled':'Disabled');render()}break;
case 'profile-edit':openForm(action);break;
case 'export-spend':exportCSV('sourcewell_demo_spend.csv',['PO','Seller','Category','Item','Quantity','Unit CAD','Line CAD','PO Status'],db.orders.flatMap(p=>p.items.map(i=>[p.id,sup(p.supplier),prod(i.product).category,prod(i.product).name,i.qty,i.price,i.price*i.qty,p.status])));toast('Spend CSV created from current demo data.');break;
case 'export-audit':exportCSV('sourcewell_demo_audit.csv',['Time','Actor','Action','Reference','Detail'],db.audit.map(x=>[x.time,x.by,x.action,x.subject,x.detail]));toast('Audit CSV exported.');break;
case 'export-json':download('sourcewell_demo_backup.json',JSON.stringify(db,null,2),'application/json');toast('Local data backup exported.');break;
case 'reset':if(!checkRole(['admin']))return;if(window.confirm('Reset all fictional transactions, policy changes and user edits?')){db=seed();save();render();toast('Demo database reset to initial state.')}break;
default:toast('No action configured for this control.');
}}
function useForm(type,fd){const get=n=>String(fd.get(n)||'').trim(),num=n=>Number(fd.get(n)),id=get('id');switch(type){
case 'requisition-submit':{if(!checkRole(['requester']))return;let items=db.cart.map(x=>({product:x.product,qty:x.qty,price:prod(x.product).price}));if(!items.length)return;let total=items.reduce((a,x)=>a+x.price*x.qty,0),b=byid('budgets',get('department'));if(!b||total<=0||total>b.limit-b.spent){toast('Invalid order or insufficient available cost-center budget.');return}if(items.some(x=>prod(x.product).stock<x.qty||prod(x.product).status!=='Active'||byid('suppliers',prod(x.product).supplier)?.status!=='Approved')){toast('One or more sample items lack sufficient synthetic stock or seller approval.');return}let r={id:next('REQ'),owner:role,department:b.id,purpose:get('purpose'),items,total,status:'Pending approval',created:date(),notes:get('notes')};db.requisitions.unshift(r);db.cart=[];audit('REQUISITION SUBMITTED',r.id,`${money(total)}; ${r.purpose}`);close();go('requisitions');toast(`Request ${r.id} submitted to department approver.`);return}
case 'reject':{if(!checkRole(['approver']))return;let r=byid('requisitions',id);if(!r||r.status!=='Pending approval')return;r.status='Rejected';r.notes+=` | Rejected: ${get('reason')}`;audit('REQUEST REJECTED',id,get('reason'));break}
case 'po-ship':{if(!checkRole(['supplier']))return;let p=byid('orders',id);if(!p||p.supplier!=='S1'||p.status!=='Accepted'||!get('tracking'))return;p.tracking=get('tracking');p.carrier=get('carrier');p.shipCost=num('shipCost');if(byid('budgets',p.department).limit-byid('budgets',p.department).spent<p.shipCost){toast('Freight exceeds remaining budget. Finance must adjust the sample cost center.');return}byid('budgets',p.department).spent+=p.shipCost;p.total=Math.round((p.total+p.shipCost)*100)/100;p.status='Shipped';audit('SHIPMENT CREATED',id,`${p.carrier} · ${p.tracking}; fictitious freight ${money(p.shipCost)}`);break}
case 'po-receive':{if(!checkRole(['procurement']))return;let p=byid('orders',id);if(!p||!['Shipped','Part Received'].includes(p.status))return;let max=p.items.reduce((a,x)=>a+x.qty,0)-(p.received||0),q=num('qty');if(!Number.isInteger(q)||q<1||q>max){toast('Received quantity exceeds outstanding order units.');return}let rec={id:next('GR'),po:id,qty:q,created:date(),by:role,note:get('note')};db.receipts.unshift(rec);p.received=(p.received||0)+q;p.status=p.received===p.items.reduce((a,x)=>a+x.qty,0)?'Received':'Part Received';audit('GOODS RECEIVED',rec.id,`${id} · ${q} accepted units`);break}
case 'invoice-new':{if(!checkRole(['supplier','finance']))return;let p=byid('orders',get('po'));if(!p||role==='supplier'&&p.supplier!=='S1'||p.status==='Issued'||db.invoices.some(i=>i.po===p.id&&i.status!=='Rejected')){toast('Purchase order not eligible for invoice.');return}let amount=num('amount');if(!Number.isFinite(amount)||amount<0){toast('Invoice amount invalid.');return}let invoice={id:next('INV'),po:p.id,supplier:p.supplier,number:get('number'),amount,status:'Submitted',created:date()};db.invoices.unshift(invoice);audit('INVOICE SUBMITTED',invoice.id,`Against ${p.id}; ${money(amount)}`);break}
case 'invoice-edit':{if(!checkRole(['finance']))return;let i=byid('invoices',id);if(!i||i.status==='Paid')return;i.amount=num('amount');i.number=get('number');i.status='Submitted';audit('INVOICE CORRECTED',id,`New amount ${money(i.amount)}`);break}
case 'product-add':case 'product-edit':{if(!checkRole(['supplier','procurement','admin']))return;let supplier=get('supplier');if(role==='supplier'&&supplier!=='S1')return;let p=id?byid('products',id):null;if(p&&role==='supplier'&&p.supplier!=='S1')return;let n={name:get('name'),sku:get('sku'),category:get('category'),supplier,price:num('price'),unit:get('unit'),stock:num('stock'),status:role==='supplier'?'Review':'Active'};if(!CATS.includes(n.category)||!byid('suppliers',supplier)||n.price<=0||!Number.isInteger(n.stock)||n.stock<0){toast('Invalid catalog data.');return}if(p)Object.assign(p,n);else{p={id:next('P'),...n};db.products.unshift(p)}audit(role==='supplier'?'CATALOG PROPOSAL':'CATALOG UPDATED',p.sku,`${p.name}; ${money(p.price)}`);break}
case 'supplier-new':case 'supplier-edit':{if(!checkRole(['procurement','admin']))return;let s=id?byid('suppliers',id):null;let data={name:get('name'),category:get('category'),region:get('region'),contact:get('contact'),diversity:get('diversity')};if(s)Object.assign(s,data);else{s={id:next('S'),...data,status:'Pending'};db.suppliers.unshift(s)}audit('SELLER RECORD UPDATED',s.name,`${s.status}; diversity ${s.diversity}`);break}
case 'contract-new':case 'contract-edit':{if(!checkRole(['procurement','admin']))return;let c=id?byid('contracts',id):null;let data={name:get('name'),supplier:get('supplier'),ceiling:num('ceiling'),expires:get('expires'),status:get('status'),terms:get('terms')};if(!byid('suppliers',data.supplier)||data.ceiling<=0){toast('Invalid contract.');return}if(c)Object.assign(c,data);else{c={id:next('CON'),...data,spent:0};db.contracts.unshift(c)}audit('CONTRACT SAVED',c.id,`${c.name}; ceiling ${money(c.ceiling)}`);break}
case 'budget-edit':{if(!checkRole(['finance']))return;let b=byid('budgets',id);if(!b||num('limit')<b.spent){toast('Budget cannot be below committed spending.');return}b.limit=num('limit');audit('BUDGET UPDATED',id,`${money(b.limit)}; ${get('reason')}`);break}
case 'policy-edit':{if(!checkRole(['admin']))return;if([num('approvalLimit'),num('taxRate'),num('variance')].some(v=>!Number.isFinite(v)||v<0)||num('taxRate')>25){toast('Invalid spending policy values.');return}db.policies.approvalLimit=num('approvalLimit');db.policies.taxRate=num('taxRate');db.policies.variance=num('variance');audit('PURCHASING POLICY UPDATED','POLICY',JSON.stringify(db.policies));break}
case 'tax-new':{if(!checkRole(['admin']))return;let t={id:next('TAX'),entity:get('entity'),certificate:get('certificate'),expiry:get('expiry'),status:'Needs validation'};db.tax.unshift(t);audit('TAX CERTIFICATE ENTERED',t.id,'Unverified demo reference');break}
case 'profile-edit':{let u=byid('users',role);u.name=get('name');u.email=get('email');audit('DEMO PROFILE UPDATED',role,`Display name: ${u.name}`);break}
default:toast('Unknown form action.');return
}close();render();toast('Changes saved. Linked screens have been updated.')}
function download(filename,data,mime){let blob=new Blob([data],{type:mime});let url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200)}
function exportCSV(filename,headers,rows){let csv=[headers,...rows].map(row=>row.map(x=>{let v=String(x??'');if(/^[=+\-@]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'}).join(',')).join('\r\n');download(filename,'\ufeff'+csv,'text/csv;charset=utf-8')}
// Event delegation prevents inert controls when views are re-rendered.
document.addEventListener('click',e=>{let el=e.target.closest('[data-action],[data-page]');if(!el)return;if(el.dataset.page){close();go(el.dataset.page);return}if(el.dataset.action){e.preventDefault();run(el.dataset.action,el.dataset.id||'',el)}});
document.addEventListener('change',e=>{if(e.target.id==='category-filter'){ui.category=e.target.value;$('#main').innerHTML=view()}if(e.target.id==='status-filter'){ui.filter=e.target.value;$('#main').innerHTML=view()}if(e.target.name==='po'&&e.target.closest('form[data-form=invoice-new]')){let selected=byid('orders',e.target.value),amt=document.querySelector('#modal input[name=amount]');if(selected&&amt)amt.value=selected.total}if(e.target.dataset.qty){if(!checkRole(['requester']))return;let p=db.cart.find(x=>x.product===e.target.dataset.qty);if(!p)return;let q=Number(e.target.value);if(!Number.isInteger(q)||q<1||q>999){toast('Quantity must be between 1 and 999.');e.target.value=p.qty;return}p.qty=q;audit('BASKET QUANTITY CHANGED',p.product,`Quantity ${q}`);$('#main').innerHTML=view()}});
document.addEventListener('input',e=>{if(e.target.id==='page-search'){let index=e.target.selectionStart;ui.search=e.target.value;$('#main').innerHTML=view();let f=$('#page-search');if(f){f.focus();f.setSelectionRange(index,index)}}if(e.target.id==='global-search'&&e.target.value.trim().length>=2){let q=e.target.value.trim().toLowerCase(),p=db.products.find(x=>x.name.toLowerCase().includes(q)||x.sku.toLowerCase().includes(q)),r=db.requisitions.find(x=>x.id.toLowerCase().includes(q)||x.purpose.toLowerCase().includes(q)),o=db.orders.find(x=>x.id.toLowerCase().includes(q));let target=p?'catalog':r?'requisitions':o?'orders':null;if(target&&allow(target)){page=target;ui.search=e.target.value;$('#main').innerHTML=view()}}});
document.addEventListener('submit',e=>{let f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();if(!f.reportValidity())return;useForm(f.dataset.form,new FormData(f))});
$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')close()});
render();
